import { useEffect, useState } from 'react';
import type { ReactNode, FormEvent, InputHTMLAttributes, ButtonHTMLAttributes, SelectHTMLAttributes } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import {
  useGetDashboard, getGetDashboardQueryKey,
  useGetSchools, getGetSchoolsQueryKey, useCreateSchool, useUpdateSchoolStatus,
  useGetClasses, getGetClassesQueryKey, useCreateClass,
  useGetStudents, getGetStudentsQueryKey, useCreateStudent,
  useGetFinanceOverview, getGetFinanceOverviewQueryKey, useGetFees, getGetFeesQueryKey, useCreateFee,
  useGetExpenses, getGetExpensesQueryKey, useCreateExpense,
  useGetGradeSheet, getGetGradeSheetQueryKey, useGetGradeSheetForTrimester,
  getGetGradeSheetForTrimesterQueryKey, useUpdateGradeSheet,
} from '@workspace/api-client-react';
import {
  ArrowDownRight, ArrowUpRight, Banknote, BarChart3, BookOpen, CalendarDays, Check, ChevronDown,
  CircleAlert, CircleDollarSign, ClipboardList, FileText, GraduationCap, LayoutDashboard, Menu,
  MoreHorizontal, PanelLeftClose, Pencil, Plus, Printer, Receipt, Search, Settings, ShieldCheck,
  SlidersHorizontal, UserPlus, Users, WalletCards, X, Landmark, Laptop
} from 'lucide-react';
import { Link, Route, Switch, useLocation } from 'wouter';

const queryClient = new QueryClient();
const money = (n = 0) => new Intl.NumberFormat('pt-PT', { style: 'currency', currency: 'XOF', maximumFractionDigits: 0 }).format(n).replace('XOF', 'FCFA');
const date = (v?: string | null) => v ? new Intl.DateTimeFormat('pt-PT', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(v)) : '—';
const initials = (name = '') => name.split(' ').slice(0, 2).map((x) => x[0]).join('').toUpperCase();

function Skeleton({ className = '' }: { className?: string }) { return <div className={`animate-pulse rounded-lg bg-muted ${className}`} />; }
function Empty({ icon: Icon, title, copy }: { icon: typeof Users; title: string; copy: string }) {
  return <div className="flex flex-col items-center justify-center py-16 text-center"><div className="mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-secondary text-secondary-foreground"><Icon size={22} /></div><h3 className="font-semibold text-foreground">{title}</h3><p className="mt-1 max-w-xs text-sm text-muted-foreground">{copy}</p></div>;
}
function ErrorState({ retry }: { retry: () => void }) { return <div className="rounded-xl border border-destructive/30 bg-destructive/5 p-8 text-center"><CircleAlert className="mx-auto mb-3 text-destructive" size={24} /><p className="font-semibold">Não foi possível carregar os dados.</p><button onClick={retry} className="mt-3 rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground" data-testid="button-retry">Tentar novamente</button></div>; }
function Badge({ children, tone = 'muted' }: { children: string; tone?: 'good' | 'warn' | 'bad' | 'muted' }) { const c = { good: 'bg-emerald-100 text-emerald-800', warn: 'bg-amber-100 text-amber-800', bad: 'bg-red-100 text-red-800', muted: 'bg-muted text-muted-foreground' }[tone]; return <span className={`inline-flex rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-wide ${c}`}>{children}</span>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="grid gap-1.5 text-xs font-semibold text-muted-foreground">{label}{children}</label>; }
function Input({ label, ...props }: InputHTMLAttributes<HTMLInputElement> & { label?: string }) { const input = <input {...props} className={`h-10 w-full rounded-lg border border-input bg-card px-3 text-sm text-foreground outline-none placeholder:text-muted-foreground/70 focus:border-accent focus:ring-2 focus:ring-accent/30 ${props.className ?? ''}`} />; return label ? <Field label={label}>{input}</Field> : input; }
function Select({ label, children, ...props }: SelectHTMLAttributes<HTMLSelectElement> & { label?: string }) { const el = <select {...props} className={`h-10 w-full appearance-none rounded-lg border border-input bg-card px-3 text-sm text-foreground outline-none focus:border-accent focus:ring-2 focus:ring-accent/30 ${props.className ?? ''}`}>{children}</select>; return label ? <Field label={label}>{el}</Field> : el; }
function Button({ children, variant = 'primary', ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'ghost' | 'soft' | 'danger' }) { const styles = { primary: 'bg-primary text-primary-foreground hover:bg-primary/90', ghost: 'border border-border bg-card text-foreground hover:bg-muted', soft: 'bg-accent text-accent-foreground hover:bg-accent/85', danger: 'border border-red-200 bg-red-50 text-red-700 hover:bg-red-100' }[variant]; return <button {...props} className={`inline-flex h-10 items-center justify-center gap-2 rounded-lg px-3.5 text-sm font-bold disabled:cursor-not-allowed disabled:opacity-50 ${styles} ${props.className ?? ''}`} />; }

const nav = [
  { href: '/', label: 'Visão geral', icon: LayoutDashboard },
  { href: '/students', label: 'Alunos', icon: Users },
  { href: '/classes', label: 'Classes', icon: BookOpen },
  { href: '/finance', label: 'Finanças', icon: WalletCards },
  { href: '/grades', label: 'Pautas e notas', icon: ClipboardList },
  { href: '/informatics', label: 'Informática', icon: Laptop },
  { href: '/documents', label: 'Documentos', icon: FileText },
];
function Shell({ children }: { children: React.ReactNode }) {
  const [location] = useLocation(); const [open, setOpen] = useState(false);
  return <div className="app-noise flex min-h-[100dvh] bg-background">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-64 flex-col bg-sidebar px-4 py-5 text-sidebar-foreground shadow-xl transition-transform md:static md:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="mb-10 flex items-center gap-3 px-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-accent text-primary"><GraduationCap size={23} strokeWidth={2.5} /></div><div><p className="font-display text-lg font-bold tracking-tight">nô<span className="text-accent">skola</span></p><p className="font-mono text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/60">gestão escolar</p></div><button className="ml-auto text-sidebar-foreground/50 md:hidden" onClick={() => setOpen(false)} data-testid="button-close-menu"><X size={18} /></button></div>
      <div className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-sidebar-foreground/45">O seu escritório</div>
      <nav className="space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-nav-${label}`} className={`group flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold ${location === href ? 'bg-accent text-primary' : 'text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-foreground'}`}><Icon size={18} /><span>{label}</span>{href === '/finance' && <span className="ml-auto h-2 w-2 rounded-full bg-accent" />}</Link>)}</nav>
      <div className="mt-8 mb-3 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-sidebar-foreground/45">Administração</div>
      <nav className="space-y-1"><Link href="/schools" data-testid="link-nav-schools" className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold ${location === '/schools' ? 'bg-accent text-primary' : 'text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-foreground'}`}><Landmark size={18} /><span>Escolas</span></Link><Link href="/settings" data-testid="link-nav-settings" className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold ${location === '/settings' ? 'bg-accent text-primary' : 'text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-foreground'}`}><Settings size={18} /><span>Definições</span></Link></nav>
      <div className="mt-auto rounded-2xl border border-sidebar-border bg-sidebar-accent/60 p-3"><p className="font-mono text-[10px] uppercase tracking-wider text-sidebar-foreground/50">Escola actual</p><p className="mt-1 text-sm font-bold">Escola Comunitária de Bissau</p><p className="mt-1 text-xs text-sidebar-foreground/55">Bissau · 2025/2026</p><button className="mt-3 flex items-center gap-1 text-xs font-bold text-accent" data-testid="button-switch-school">Mudar escola <ChevronDown size={13} /></button></div>
    </aside>
    {open && <button className="fixed inset-0 z-30 bg-primary/40 md:hidden" onClick={() => setOpen(false)} aria-label="Fechar menu" data-testid="button-overlay" />}
    <div className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-border/70 bg-background/90 px-5 backdrop-blur md:px-9"><div className="flex items-center gap-3"><button className="rounded-lg p-2 hover:bg-muted md:hidden" onClick={() => setOpen(true)} data-testid="button-open-menu"><Menu size={20} /></button><div className="hidden items-center gap-2 text-xs text-muted-foreground md:flex"><span>Quarta-feira, 18 de Setembro</span><span className="h-1 w-1 rounded-full bg-accent" /><span className="font-mono text-[11px]">08:42</span></div></div><div className="flex items-center gap-4"><button className="relative rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-foreground" data-testid="button-notifications"><CircleAlert size={19} /><span className="absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-accent" /></button><div className="hidden h-7 w-px bg-border sm:block" /><div className="flex items-center gap-2"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-secondary text-xs font-extrabold text-secondary-foreground">AM</div><div className="hidden sm:block"><p className="text-xs font-bold">Ana Mané</p><p className="text-[10px] text-muted-foreground">Direcção</p></div><ChevronDown size={15} className="text-muted-foreground" /></div></div></header><main className="mx-auto max-w-[1500px] px-5 py-7 md:px-9 md:py-9">{children}</main></div>
  </div>;
}
function PageIntro({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy?: string; action?: ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="mb-2 font-mono text-[10px] font-medium uppercase tracking-[.2em] text-muted-foreground">{eyebrow}</p><h1 className="font-display text-3xl font-bold tracking-tight text-foreground md:text-4xl">{title}</h1>{copy && <p className="mt-2 text-sm text-muted-foreground">{copy}</p>}</div>{action}</div>; }
function Stat({ icon: Icon, label, value, trend, tone = 'dark' }: { icon: typeof Users; label: string; value: string; trend?: string; tone?: 'dark' | 'yellow' | 'green' | 'red' }) { const colors = { dark: 'bg-primary text-primary-foreground', yellow: 'bg-accent text-accent-foreground', green: 'bg-secondary text-secondary-foreground', red: 'bg-[#f6dfd8] text-[#7d3228]' }; return <div className={`rounded-2xl p-5 ${colors[tone]}`}><div className="flex items-start justify-between"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-black/10"><Icon size={18} /></div>{trend && <span className="font-mono text-[10px] opacity-70">{trend}</span>}</div><p className="mt-6 text-xs font-semibold opacity-70">{label}</p><p className="mt-1 font-display text-2xl font-bold tracking-tight">{value}</p></div>; }

function Dashboard() {
  const q = useGetDashboard(); const data = q.data;
  if (q.isLoading) return <><PageIntro eyebrow="painel de controlo" title="Bom dia, Ana." copy="O retrato da sua escola, num só lugar." /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[1,2,3,4].map(i => <Skeleton key={i} className="h-36" />)}</div></>;
  if (q.isError || !data) return <ErrorState retry={() => q.refetch()} />;
  const enrollmentByClass = data.enrollmentByClass ?? [];
  const totalStudents = data.totalStudents ?? 0;
  const max = Math.max(...enrollmentByClass.map(x => x.capacity), 1);
  return <div className="animate-in"><PageIntro eyebrow="quarta-feira · 18 setembro 2024" title="Bom dia, Ana." copy={`${data.schoolName} · ano lectivo ${data.academicYear}`} action={<Button variant="soft" onClick={() => window.print()} data-testid="button-print-dashboard"><Printer size={16} /> Imprimir resumo</Button>} />
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={Users} label="Alunos matriculados" value={totalStudents.toLocaleString('pt-PT')} trend="+12 este mês" /><Stat icon={Banknote} label="Propinas recebidas" value={money(data.paidFees)} trend="68% do previsto" tone="yellow" /><Stat icon={BookOpen} label="Classes activas" value={String(data.totalClasses ?? 0)} trend={`ano ${data.academicYear ?? '2025/2026'}`} tone="green" /><Stat icon={CircleDollarSign} label="Despesas registadas" value={money(data.totalExpenses)} trend="este ano" tone="red" /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_1fr]"><section className="rounded-2xl border border-border bg-card p-5 md:p-6"><div className="flex items-start justify-between"><div><h2 className="font-display text-lg font-bold">Ocupação por classe</h2><p className="mt-1 text-xs text-muted-foreground">Alunos inscritos face à capacidade disponível</p></div><Link href="/classes" className="text-xs font-bold text-secondary-foreground hover:underline" data-testid="link-dashboard-classes">Ver todas <ArrowUpRight size={13} className="ml-1 inline" /></Link></div><div className="mt-8 space-y-5">{enrollmentByClass.slice(0, 6).map((item, i) => <div key={item.className} data-testid={`row-enrollment-${i}`}><div className="mb-2 flex justify-between text-xs"><span className="font-bold">{item.className}</span><span className="font-mono text-muted-foreground">{item.students} <span className="opacity-50">/ {item.capacity}</span></span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${item.students / item.capacity > .9 ? 'bg-[#c66651]' : 'bg-secondary-foreground'}`} style={{ width: `${Math.min((item.students / max) * 100, 100)}%` }} /></div></div>)}</div></section>
      <section className="rounded-2xl bg-primary p-5 text-primary-foreground md:p-6"><div className="flex items-start justify-between"><div><h2 className="font-display text-lg font-bold">Atenção hoje</h2><p className="mt-1 text-xs text-primary-foreground/60">Pontos que pedem a sua decisão</p></div><SlidersHorizontal size={19} className="text-accent" /></div><div className="mt-7 space-y-3"><Link href="/finance" className="flex items-center gap-3 rounded-xl border border-primary-foreground/10 bg-primary-foreground/5 p-3 hover:bg-primary-foreground/10" data-testid="link-alert-finance"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-accent text-primary"><Banknote size={17} /></div><div className="min-w-0 flex-1"><p className="text-sm font-bold">Propinas pendentes</p><p className="mt-0.5 text-xs text-primary-foreground/55">{money(data.pendingFees)} por regularizar</p></div><ArrowUpRight size={16} className="text-accent" /></Link><Link href="/schools" className="flex items-center gap-3 rounded-xl border border-primary-foreground/10 bg-primary-foreground/5 p-3 hover:bg-primary-foreground/10" data-testid="link-alert-schools"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#f6dfd8] text-[#7d3228]"><Landmark size={17} /></div><div className="min-w-0 flex-1"><p className="text-sm font-bold">Adesões de escolas</p><p className="mt-0.5 text-xs text-primary-foreground/55">{data.pendingSchools} pedidos aguardam revisão</p></div><ArrowUpRight size={16} className="text-accent" /></Link><Link href="/grades" className="flex items-center gap-3 rounded-xl border border-primary-foreground/10 bg-primary-foreground/5 p-3 hover:bg-primary-foreground/10" data-testid="link-alert-grades"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-secondary text-secondary-foreground"><ClipboardList size={17} /></div><div className="min-w-0 flex-1"><p className="text-sm font-bold">Pautas do 1.º trimestre</p><p className="mt-0.5 text-xs text-primary-foreground/55">Prepare e valide as classificações</p></div><ArrowUpRight size={16} className="text-accent" /></Link></div></section></div>
    <section className="mt-5 grid gap-5 md:grid-cols-3"><div className="rounded-2xl border border-border bg-card p-5"><p className="text-xs font-bold text-muted-foreground">Alunos activos</p><p className="mt-3 font-display text-3xl font-bold">{data.activeStudents}</p><div className="mt-4 flex items-center gap-2 text-xs text-secondary-foreground"><ArrowUpRight size={14} /> em acompanhamento</div></div><div className="rounded-2xl border border-border bg-card p-5"><p className="text-xs font-bold text-muted-foreground">Alunos desistentes</p><p className="mt-3 font-display text-3xl font-bold">{data.withdrawnStudents}</p><div className="mt-4 flex items-center gap-2 text-xs text-muted-foreground"><ArrowDownRight size={14} /> do total anual</div></div><div className="rounded-2xl border border-border bg-card p-5"><p className="text-xs font-bold text-muted-foreground">Taxa de cobrança</p><p className="mt-3 font-display text-3xl font-bold">{data.paidFees + data.pendingFees ? Math.round(data.paidFees / (data.paidFees + data.pendingFees) * 100) : 0}%</p><div className="mt-4 h-1.5 rounded-full bg-muted"><div className="h-full rounded-full bg-accent" style={{ width: `${data.paidFees + data.pendingFees ? data.paidFees / (data.paidFees + data.pendingFees) * 100 : 0}%` }} /></div></div></section>
  </div>;
}

function Schools() {
  const q = useGetSchools(); const qc = useQueryClient(); const create = useCreateSchool(); const update = useUpdateSchoolStatus(); const [form, setForm] = useState(false); const [values, setValues] = useState({ name: '', city: '', contactName: '', email: '', phone: '' });
  const save = (e: FormEvent) => { e.preventDefault(); create.mutate({ data: values }, { onSuccess: () => { setForm(false); setValues({ name: '', city: '', contactName: '', email: '', phone: '' }); qc.invalidateQueries({ queryKey: getGetSchoolsQueryKey() }); } }); };
  return <div className="animate-in"><PageIntro eyebrow="administração da plataforma" title="Escolas" copy="Acompanhe adesões e mantenha a rede escolar organizada." action={<div className="flex gap-2"><Button variant="ghost" onClick={() => window.print()} data-testid="button-print-schools"><Printer size={16} /> Imprimir</Button><Button onClick={() => setForm(!form)} data-testid="button-new-school"><Plus size={17} /> Registar escola</Button></div>} />
    {form && <form onSubmit={save} className="mb-5 grid gap-3 rounded-2xl border border-accent/60 bg-accent/10 p-5 sm:grid-cols-2 lg:grid-cols-5"><Input label="Nome da escola" required value={values.name} onChange={e => setValues({ ...values, name: e.target.value })} data-testid="input-school-name" /><Input label="Cidade" required value={values.city} onChange={e => setValues({ ...values, city: e.target.value })} data-testid="input-school-city" /><Input label="Pessoa de contacto" required value={values.contactName} onChange={e => setValues({ ...values, contactName: e.target.value })} data-testid="input-school-contact" /><Input label="Email" type="email" required value={values.email} onChange={e => setValues({ ...values, email: e.target.value })} data-testid="input-school-email" /><div className="flex items-end gap-2"><Input label="Telefone" required value={values.phone} onChange={e => setValues({ ...values, phone: e.target.value })} data-testid="input-school-phone" /><Button type="submit" disabled={create.isPending} data-testid="button-save-school">{create.isPending ? 'A guardar…' : 'Guardar'}</Button></div></form>}
    <section className="overflow-hidden rounded-2xl border border-border bg-card"><div className="flex flex-col justify-between gap-3 border-b border-border p-5 sm:flex-row sm:items-center"><div><h2 className="font-display text-lg font-bold">Pedidos e escolas registadas</h2><p className="mt-1 text-xs text-muted-foreground">{q.data?.length ?? 0} escolas na plataforma</p></div><div className="flex items-center gap-2 rounded-lg border border-border px-3 py-2 text-xs text-muted-foreground"><Search size={15} /> Pesquisar escola</div></div>{q.isLoading ? <div className="space-y-3 p-5">{[1,2,3].map(i => <Skeleton key={i} className="h-14" />)}</div> : q.isError ? <ErrorState retry={() => q.refetch()} /> : !q.data?.length ? <Empty icon={Landmark} title="Ainda não há escolas" copy="Registe a primeira escola para começar a sua rede." /> : <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="bg-muted/40 text-[10px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3">Escola</th><th className="px-5 py-3">Contacto</th><th className="px-5 py-3">Alunos</th><th className="px-5 py-3">Entrada</th><th className="px-5 py-3">Estado</th><th className="px-5 py-3 text-right">Acção</th></tr></thead><tbody className="divide-y divide-border">{q.data.map(s => <tr key={s.id} className="hover:bg-muted/30" data-testid={`row-school-${s.id}`}><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-secondary text-xs font-bold text-secondary-foreground">{initials(s.name)}</div><div><p className="font-bold">{s.name}</p><p className="text-xs text-muted-foreground">{s.city}</p></div></div></td><td className="px-5 py-4"><p className="text-xs font-semibold">{s.contactName}</p><p className="text-xs text-muted-foreground">{s.phone}</p></td><td className="px-5 py-4 font-mono text-xs">{s.studentsCount}</td><td className="px-5 py-4 text-xs text-muted-foreground">{date(s.createdAt)}</td><td className="px-5 py-4"><Badge tone={s.status === 'approved' ? 'good' : s.status === 'rejected' ? 'bad' : 'warn'}>{s.status === 'approved' ? 'aprovada' : s.status === 'rejected' ? 'rejeitada' : 'pendente'}</Badge></td><td className="px-5 py-4 text-right">{s.status === 'pending' ? <div className="flex justify-end gap-2"><Button variant="soft" className="h-8 px-2.5 text-xs" disabled={update.isPending} onClick={() => update.mutate({ schoolId: s.id, data: { status: 'approved' } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetSchoolsQueryKey() }) })} data-testid={`button-approve-school-${s.id}`}><Check size={14} /> Aprovar</Button><Button variant="danger" className="h-8 px-2.5 text-xs" disabled={update.isPending} onClick={() => update.mutate({ schoolId: s.id, data: { status: 'rejected' } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetSchoolsQueryKey() }) })} data-testid={`button-reject-school-${s.id}`}><X size={14} /></Button></div> : <MoreHorizontal size={18} className="ml-auto text-muted-foreground" />}</td></tr>)}</tbody></table></div>}</section>
  </div>;
}

function Classes() {
  const q = useGetClasses(); const qc = useQueryClient(); const create = useCreateClass(); const [form, setForm] = useState(false); const [v, setV] = useState({ name: '', level: 'Jardim', section: 'A1', capacity: '30', academicYear: '2025/2026' });
  const levels = ['Jardim', '1.º ano', '2.º ano', '3.º ano', '4.º ano', '5.º ano', '6.º ano', '7.º ano', '8.º ano', '9.º ano', '10.º ano', '11.º ano', '12.º ano'];
  const save = (e: FormEvent) => { e.preventDefault(); create.mutate({ data: { ...v, schoolId: 1, capacity: Number(v.capacity) } }, { onSuccess: () => { setForm(false); qc.invalidateQueries({ queryKey: getGetClassesQueryKey() }); } }); };
  return <div className="animate-in"><PageIntro eyebrow="estrutura lectiva" title="Classes" copy="Configure níveis, turmas e a capacidade de cada sala." action={<div className="flex gap-2"><Button variant="ghost" onClick={() => window.print()} data-testid="button-print-classes"><Printer size={16} /> Imprimir</Button><Button onClick={() => setForm(!form)} data-testid="button-new-class"><Plus size={17} /> Nova classe</Button></div>} />
    {form && <form onSubmit={save} className="mb-5 grid gap-3 rounded-2xl border border-accent/60 bg-accent/10 p-5 sm:grid-cols-2 lg:grid-cols-6"><Input label="Nome da classe" placeholder="Ex.: 7.º A1" required value={v.name} onChange={e => setV({ ...v, name: e.target.value })} data-testid="input-class-name" /><Select label="Nível" value={v.level} onChange={e => setV({ ...v, level: e.target.value })} data-testid="select-class-level">{levels.map(x => <option key={x}>{x}</option>)}</Select><Select label="Subdivisão" value={v.section} onChange={e => setV({ ...v, section: e.target.value })} data-testid="select-class-section"><option>A1</option><option>A2</option><option>B1</option><option>B2</option></Select><Input label="Capacidade" type="number" min="1" required value={v.capacity} onChange={e => setV({ ...v, capacity: e.target.value })} data-testid="input-class-capacity" /><Input label="Ano lectivo" required value={v.academicYear} onChange={e => setV({ ...v, academicYear: e.target.value })} data-testid="input-class-year" /><div className="flex items-end"><Button type="submit" disabled={create.isPending} data-testid="button-save-class">{create.isPending ? 'A guardar…' : 'Criar classe'}</Button></div></form>}
    {q.isLoading ? <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{[1,2,3,4,5,6].map(i => <Skeleton key={i} className="h-40" />)}</div> : q.isError ? <ErrorState retry={() => q.refetch()} /> : !q.data?.length ? <div className="rounded-2xl border border-border bg-card"><Empty icon={BookOpen} title="A sua estrutura começa aqui" copy="Crie a primeira turma para poder matricular alunos." /></div> : <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{q.data.map((c, i) => { const pct = c.capacity ? Math.round(c.enrolledCount / c.capacity * 100) : 0; return <article key={c.id} className="group rounded-2xl border border-border bg-card p-5 hover:-translate-y-0.5 hover:border-accent hover:shadow-lg hover:shadow-primary/5" data-testid={`card-class-${c.id}`}><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-secondary text-secondary-foreground"><BookOpen size={19} /></div><button className="rounded-lg p-1.5 text-muted-foreground hover:bg-muted" data-testid={`button-class-menu-${c.id}`}><MoreHorizontal size={18} /></button></div><h3 className="mt-5 font-display text-xl font-bold">{c.name}</h3><div className="mt-1 flex items-center gap-2 text-xs text-muted-foreground"><span>{c.level}</span><span className="h-1 w-1 rounded-full bg-accent" /><span>Turma {c.section}</span></div><div className="mt-6"><div className="mb-2 flex justify-between text-xs"><span className="text-muted-foreground">Ocupação</span><span className="font-mono font-bold">{c.enrolledCount}/{c.capacity}</span></div><div className="h-2 rounded-full bg-muted"><div className={`h-full rounded-full ${pct > 90 ? 'bg-[#c66651]' : 'bg-secondary-foreground'}`} style={{ width: `${Math.min(pct,100)}%` }} /></div></div></article> })}</div>}
  </div>;
}

function Students() {
  const [search, setSearch] = useState(''); const q = useGetStudents(search ? { search } : undefined); const classes = useGetClasses(); const qc = useQueryClient(); const create = useCreateStudent(); const [form, setForm] = useState(false); const [v, setV] = useState({ name: '', gender: 'F', birthDate: '', guardianName: '', phone: '', classGroupId: '', feeStatus: 'pending' });
  const save = (e: FormEvent) => { e.preventDefault(); if (!v.classGroupId) return; create.mutate({ data: { name: v.name, gender: v.gender as 'F' | 'M', birthDate: v.birthDate || null, guardianName: v.guardianName, phone: v.phone, classGroupId: Number(v.classGroupId), feeStatus: v.feeStatus as 'paid' | 'partial' | 'pending' } }, { onSuccess: () => { setForm(false); setV({ name: '', gender: 'F', birthDate: '', guardianName: '', phone: '', classGroupId: '', feeStatus: 'pending' }); qc.invalidateQueries({ queryKey: getGetStudentsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); } }); };
  return <div className="animate-in"><PageIntro eyebrow="registo escolar" title="Alunos" copy="Encontre qualquer aluno e mantenha as matrículas em dia." action={<div className="flex gap-2"><Button variant="ghost" onClick={() => window.print()} data-testid="button-print-students"><Printer size={16} /> Imprimir</Button><Button onClick={() => setForm(!form)} data-testid="button-new-student"><UserPlus size={17} /> Matricular aluno</Button></div>} />
    {form && <form onSubmit={save} className="mb-5 grid gap-3 rounded-2xl border border-accent/60 bg-accent/10 p-5 sm:grid-cols-2 lg:grid-cols-4"><Input label="Nome completo" required value={v.name} onChange={e => setV({ ...v, name: e.target.value })} data-testid="input-student-name" /><Select label="Sexo" value={v.gender} onChange={e => setV({ ...v, gender: e.target.value })} data-testid="select-student-gender"><option value="F">Feminino</option><option value="M">Masculino</option></Select><Input label="Data de nascimento" type="date" value={v.birthDate} onChange={e => setV({ ...v, birthDate: e.target.value })} data-testid="input-student-birthdate" /><Select label="Classe (obrigatório)" required value={v.classGroupId} onChange={e => setV({ ...v, classGroupId: e.target.value })} data-testid="select-student-class"><option value="">Escolher classe…</option>{classes.data?.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</Select><Input label="Encarregado de educação" required value={v.guardianName} onChange={e => setV({ ...v, guardianName: e.target.value })} data-testid="input-student-guardian" /><Input label="Telefone" required value={v.phone} onChange={e => setV({ ...v, phone: e.target.value })} data-testid="input-student-phone" /><Select label="Estado da propina" value={v.feeStatus} onChange={e => setV({ ...v, feeStatus: e.target.value })} data-testid="select-student-fee"><option value="pending">Pendente</option><option value="partial">Parcial</option><option value="paid">Pago</option></Select><div className="flex items-end"><Button type="submit" disabled={create.isPending || !v.classGroupId} data-testid="button-save-student">{create.isPending ? 'A matricular…' : 'Confirmar matrícula'}</Button></div></form>}
    <section className="rounded-2xl border border-border bg-card"><div className="flex flex-col gap-4 border-b border-border p-5 md:flex-row md:items-center md:justify-between"><div><h2 className="font-display text-lg font-bold">Todos os alunos</h2><p className="mt-1 text-xs text-muted-foreground">Pesquisa por nome ou código de aluno</p></div><div className="flex h-10 w-full items-center gap-2 rounded-lg border border-input bg-background px-3 md:max-w-xs"><Search size={16} className="text-muted-foreground" /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Pesquisar…" className="min-w-0 flex-1 bg-transparent text-sm outline-none" data-testid="input-search-students" /></div></div>{q.isLoading ? <div className="space-y-3 p-5">{[1,2,3,4].map(i => <Skeleton key={i} className="h-14" />)}</div> : q.isError ? <ErrorState retry={() => q.refetch()} /> : !q.data?.length ? <Empty icon={Users} title="Nenhum aluno encontrado" copy={search ? 'Tente outro nome ou código.' : 'Matricule o primeiro aluno da escola.'} /> : <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="bg-muted/40 text-[10px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3">Aluno</th><th className="px-5 py-3">Classe</th><th className="px-5 py-3">Encarregado</th><th className="px-5 py-3">Matrícula</th><th className="px-5 py-3">Propina</th></tr></thead><tbody className="divide-y divide-border">{q.data.map(s => <tr key={s.id} className="hover:bg-muted/30" data-testid={`row-student-${s.id}`}><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-accent text-[10px] font-extrabold text-accent-foreground">{initials(s.name)}</div><div><p className="font-bold">{s.name}</p><p className="font-mono text-[10px] text-muted-foreground">{s.studentCode}</p></div></div></td><td className="px-5 py-4"><span className="rounded-md bg-secondary px-2 py-1 text-xs font-bold text-secondary-foreground">{s.className}</span></td><td className="px-5 py-4"><p className="text-xs font-semibold">{s.guardianName}</p><p className="text-xs text-muted-foreground">{s.phone}</p></td><td className="px-5 py-4 text-xs text-muted-foreground">{date(s.enrolledAt)}</td><td className="px-5 py-4"><Badge tone={s.feeStatus === 'paid' ? 'good' : s.feeStatus === 'partial' ? 'warn' : 'bad'}>{s.feeStatus === 'paid' ? 'paga' : s.feeStatus === 'partial' ? 'parcial' : 'pendente'}</Badge></td></tr>)}</tbody></table></div>}</section>
  </div>;
}

function Finance() {
  const overview = useGetFinanceOverview(); const fees = useGetFees(); const expenses = useGetExpenses(); const qc = useQueryClient(); const feeCreate = useCreateFee(); const expenseCreate = useCreateExpense(); const students = useGetStudents() as { data?: Array<{ id: number; name: string; studentName?: string }> }; const [tab, setTab] = useState<'fees' | 'expenses'>('fees'); const [show, setShow] = useState(false);
  const [fv, setFv] = useState({ studentId: '', amount: '', paidAmount: '', dueDate: '', reference: '' }); const [ev, setEv] = useState({ description: '', category: 'Material escolar', amount: '', date: '', paidBy: '' });
  const saveFee = (e: FormEvent) => { e.preventDefault(); feeCreate.mutate({ data: { studentId: Number(fv.studentId), amount: Number(fv.amount), paidAmount: Number(fv.paidAmount), dueDate: fv.dueDate, reference: fv.reference } }, { onSuccess: () => { setShow(false); qc.invalidateQueries({ queryKey: getGetFeesQueryKey() }); qc.invalidateQueries({ queryKey: getGetFinanceOverviewQueryKey() }); } }); };
  const saveExpense = (e: FormEvent) => { e.preventDefault(); expenseCreate.mutate({ data: { description: ev.description, category: ev.category, amount: Number(ev.amount), date: ev.date, paidBy: ev.paidBy } }, { onSuccess: () => { setShow(false); qc.invalidateQueries({ queryKey: getGetExpensesQueryKey() }); qc.invalidateQueries({ queryKey: getGetFinanceOverviewQueryKey() }); } }); };
  const o = overview.data;
  return <div className="animate-in"><PageIntro eyebrow="contabilidade escolar" title="Finanças" copy="O pulso financeiro da escola, sem contas escondidas." action={<div className="flex gap-2"><Button variant="ghost" onClick={() => window.print()} data-testid="button-print-finance"><Printer size={16} /> Imprimir</Button><Button onClick={() => setShow(!show)} data-testid="button-new-transaction"><Plus size={17} /> Registar movimento</Button></div>} />
    {show && <form onSubmit={tab === 'fees' ? saveFee : saveExpense} className="mb-5 grid gap-3 rounded-2xl border border-accent/60 bg-accent/10 p-5 sm:grid-cols-2 lg:grid-cols-5">{tab === 'fees' ? <><Select label="Aluno" required value={fv.studentId} onChange={e => setFv({ ...fv, studentId: e.target.value })} data-testid="select-fee-student"><option value="">Escolher aluno…</option>{students.data?.map(s => <option key={s.id} value={s.id}>{s.studentName ?? s.name}</option>)}</Select><Input label="Valor previsto" type="number" min="0" required value={fv.amount} onChange={e => setFv({ ...fv, amount: e.target.value })} data-testid="input-fee-amount" /><Input label="Valor recebido" type="number" min="0" required value={fv.paidAmount} onChange={e => setFv({ ...fv, paidAmount: e.target.value })} data-testid="input-fee-paid" /><Input label="Vencimento" type="date" required value={fv.dueDate} onChange={e => setFv({ ...fv, dueDate: e.target.value })} data-testid="input-fee-due" /><div className="flex items-end"><Button type="submit" disabled={feeCreate.isPending} data-testid="button-save-fee">Guardar propina</Button></div></> : <><Input label="Descrição" required value={ev.description} onChange={e => setEv({ ...ev, description: e.target.value })} data-testid="input-expense-description" /><Input label="Categoria" required value={ev.category} onChange={e => setEv({ ...ev, category: e.target.value })} data-testid="input-expense-category" /><Input label="Valor" type="number" min="0" required value={ev.amount} onChange={e => setEv({ ...ev, amount: e.target.value })} data-testid="input-expense-amount" /><Input label="Data" type="date" required value={ev.date} onChange={e => setEv({ ...ev, date: e.target.value })} data-testid="input-expense-date" /><div className="flex items-end"><Button type="submit" disabled={expenseCreate.isPending} data-testid="button-save-expense">Guardar despesa</Button></div></>}</form>}
    {overview.isLoading ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5">{[1,2,3,4,5].map(i => <Skeleton key={i} className="h-28" />)}</div> : overview.isError || !o ? <ErrorState retry={() => overview.refetch()} /> : <><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Stat icon={BarChart3} label="Receita esperada" value={money(o.expectedFees)} /><Stat icon={Banknote} label="Recebido" value={money(o.receivedFees)} tone="yellow" /><Stat icon={CircleAlert} label="Por receber" value={money(o.pendingFees)} tone="red" /><Stat icon={Receipt} label="Despesas" value={money(o.expenses)} tone="green" /><Stat icon={WalletCards} label="Saldo corrente" value={money(o.balance)} /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.2fr_1fr]"><section className="rounded-2xl border border-border bg-card p-5 md:p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Movimentos recentes</h2><p className="mt-1 text-xs text-muted-foreground">Registo financeiro da escola</p></div><div className="flex rounded-lg bg-muted p-1"><button onClick={() => setTab('fees')} className={`rounded-md px-3 py-1.5 text-xs font-bold ${tab === 'fees' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} data-testid="tab-fees">Propinas</button><button onClick={() => setTab('expenses')} className={`rounded-md px-3 py-1.5 text-xs font-bold ${tab === 'expenses' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} data-testid="tab-expenses">Despesas</button></div></div>{tab === 'fees' ? <div className="mt-5 divide-y divide-border">{fees.isLoading ? <Skeleton className="h-40" /> : !fees.data?.length ? <Empty icon={Receipt} title="Sem propinas registadas" copy="Os pagamentos aparecerão aqui." /> : fees.data.slice(0, 6).map(f => <div className="flex items-center gap-3 py-3" key={f.id} data-testid={`row-fee-${f.id}`}><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-secondary text-secondary-foreground"><Banknote size={15} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{f.studentName}</p><p className="text-[11px] text-muted-foreground">{f.reference || 'Sem referência'} · venc. {date(f.dueDate)}</p></div><div className="text-right"><p className="font-mono text-xs font-bold">{money(f.paidAmount)}</p><Badge tone={f.status === 'paid' ? 'good' : f.status === 'partial' ? 'warn' : 'bad'}>{f.status === 'paid' ? 'paga' : f.status === 'partial' ? 'parcial' : 'pendente'}</Badge></div></div>)}</div> : <div className="mt-5 divide-y divide-border">{expenses.isLoading ? <Skeleton className="h-40" /> : !expenses.data?.length ? <Empty icon={Receipt} title="Sem despesas registadas" copy="As despesas aparecerão aqui." /> : expenses.data.slice(0, 6).map(x => <div className="flex items-center gap-3 py-3" key={x.id} data-testid={`row-expense-${x.id}`}><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#f6dfd8] text-[#7d3228]"><ArrowDownRight size={15} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{x.description}</p><p className="text-[11px] text-muted-foreground">{x.category} · {date(x.date)}</p></div><p className="font-mono text-xs font-bold text-[#9b4738]">− {money(x.amount)}</p></div>)}</div>}</section><section className="rounded-2xl bg-primary p-5 text-primary-foreground md:p-6"><h2 className="font-display text-lg font-bold">Ritmo mensal</h2><p className="mt-1 text-xs text-primary-foreground/60">Receita vs. despesa</p><div className="mt-8 flex h-44 items-end gap-3 border-b border-primary-foreground/15 pb-0">{o.monthly.map(m => { const h = Math.max(...o.monthly.map(x => Math.max(x.income, x.expenses)), 1); return <div className="flex flex-1 flex-col items-center gap-2" key={m.month} data-testid={`chart-month-${m.month}`}><div className="flex h-32 w-full max-w-8 items-end gap-0.5"><div className="w-1/2 rounded-t-sm bg-accent" style={{ height: `${m.income / h * 100}%` }} /><div className="w-1/2 rounded-t-sm bg-secondary-foreground/60" style={{ height: `${m.expenses / h * 100}%` }} /></div><span className="font-mono text-[9px] text-primary-foreground/50">{m.month.slice(0,3)}</span></div> })}</div><div className="mt-5 flex gap-4 text-[10px] text-primary-foreground/60"><span><i className="mr-1 inline-block h-2 w-2 rounded-full bg-accent" />receita</span><span><i className="mr-1 inline-block h-2 w-2 rounded-full bg-secondary-foreground/60" />despesas</span></div></section></div></>}
  </div>;
}

function GradesLegacy() {
  const classes = useGetClasses(); const [classId, setClassId] = useState(''); const [trimester, setTrimester] = useState('1'); const id = Number(classId) || 0; const sheet = useGetGradeSheet(id, { query: { enabled: !!id, queryKey: getGetGradeSheetQueryKey(id) } }); const trim = useGetGradeSheetForTrimester(id, Number(trimester), { query: { enabled: !!id, queryKey: getGetGradeSheetForTrimesterQueryKey(id, Number(trimester)) } }); const update = useUpdateGradeSheet(); const qc = useQueryClient(); const data = trim.data ?? sheet.data; const [scores, setScores] = useState<Record<string, string>>({});
  const setScore = (studentId: number, subject: string, field: string, value: string) => setScores({ ...scores, [`${studentId}-${subject}-${field}`]: value });
  const save = () => { if (!data) return; const students = data.students.map(s => ({ ...s, scores: s.scores.map(sc => ({ ...sc, period1: scores[`${s.studentId}-${sc.subject}-period1`] === undefined ? sc.period1 : Number(scores[`${s.studentId}-${sc.subject}-period1`]) })) })); update.mutate({ classGroupId: id, data: { trimester: Number(trimester), subjects: data.subjects, students } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetGradeSheetForTrimesterQueryKey(id, Number(trimester)) }) }); };
  return <div className="animate-in"><PageIntro eyebrow="avaliação oficial" title="Pautas e notas" copy="Registe, reveja e imprima as classificações por trimestre." action={data ? <div className="flex gap-2"><Button variant="ghost" onClick={() => window.print()} data-testid="button-print-grades"><Printer size={16} /> Imprimir A4</Button><Button onClick={save} disabled={update.isPending} data-testid="button-save-grades">{update.isPending ? 'A guardar…' : 'Guardar alterações'}</Button></div> : undefined} /><div className="mb-5 flex flex-col gap-3 rounded-2xl border border-border bg-card p-4 sm:flex-row sm:items-end"><Select label="Classe" value={classId} onChange={e => setClassId(e.target.value)} data-testid="select-grade-class"><option value="">Escolher classe…</option>{classes.data?.map(c => <option key={c.id} value={c.id}>{c.name} · {c.academicYear}</option>)}</Select><Select label="Trimestre" value={trimester} onChange={e => setTrimester(e.target.value)} data-testid="select-grade-trimester"><option value="1">1.º trimestre</option><option value="2">2.º trimestre</option><option value="3">3.º trimestre</option></Select><div className="hidden text-xs text-muted-foreground sm:block sm:pb-3"><CalendarDays size={15} className="mr-1 inline" /> As notas são guardadas por aluno e disciplina</div></div>{!classId ? <div className="rounded-2xl border border-border bg-card"><Empty icon={ClipboardList} title="Escolha uma classe para começar" copy="Seleccione a turma e o trimestre para abrir a pauta oficial." /></div> : sheet.isLoading || trim.isLoading ? <Skeleton className="h-72" /> : sheet.isError || trim.isError ? <ErrorState retry={() => { sheet.refetch(); trim.refetch(); }} /> : !data ? <div className="rounded-2xl border border-border bg-card"><Empty icon={ClipboardList} title="Pauta vazia" copy="Esta classe ainda não tem alunos ou disciplinas configuradas." /></div> : <section className="print-sheet overflow-hidden rounded-2xl border border-border bg-card"><div className="border-b border-border bg-primary p-5 text-primary-foreground md:p-6"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-widest text-accent">Documento oficial · classificação</p><h2 className="mt-2 font-display text-2xl font-bold">{data.className}</h2><p className="mt-1 text-xs text-primary-foreground/60">Ano lectivo {data.academicYear} · {data.trimester}.º trimestre</p></div><div className="hidden h-12 w-12 items-center justify-center rounded-xl bg-accent text-primary sm:flex"><GraduationCap size={25} /></div></div></div><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-xs"><thead className="bg-muted/50 text-[10px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-4 py-3">Aluno</th>{data.subjects.slice(0, 4).map(sub => <th key={sub} className="px-3 py-3" colSpan={2}>{sub}</th>)}<th className="px-3 py-3">Média final</th></tr><tr className="border-t border-border/50"><th className="px-4 py-2 font-normal">Código · nome</th>{data.subjects.slice(0, 4).flatMap(sub => [<th key={`${sub}-p`} className="px-3 py-2 font-normal">P{data.trimester}</th>, <th key={`${sub}-m`} className="px-3 py-2 font-normal">Média</th>])}<th className="px-3 py-2 font-normal">Resultado</th></tr></thead><tbody className="divide-y divide-border">{data.students.map(s => { const avgs = s.scores.map(x => x.average).filter((x): x is number => x !== null); const avg = avgs.length ? avgs.reduce((a,b) => a+b,0)/avgs.length : null; return <tr key={s.studentId} className="hover:bg-muted/20" data-testid={`row-grade-${s.studentId}`}><td className="px-4 py-3"><p className="font-bold">{s.studentName}</p><p className="font-mono text-[10px] text-muted-foreground">{s.studentCode}</p></td>{data.subjects.slice(0, 4).flatMap(sub => { const sc = s.scores.find(x => x.subject === sub); return [<td key={`${s.studentId}-${sub}-input`} className="px-3 py-3"><input type="number" min="0" max="20" step=".1" value={scores[`${s.studentId}-${sub}-period1`] ?? sc?.period1 ?? ''} onChange={e => setScore(s.studentId, sub, 'period1', e.target.value)} className="h-8 w-14 rounded-md border border-input bg-background px-2 text-center font-mono text-xs outline-none focus:border-accent" data-testid={`input-grade-${s.studentId}-${sub}`} /></td>, <td key={`${s.studentId}-${sub}-avg`} className="px-3 py-3 font-mono">{sc?.average?.toFixed(1) ?? '—'}</td>]})}<td className="px-3 py-3">{avg !== null ? <Badge tone={avg >= 10 ? 'good' : 'bad'}>{avg >= 10 ? `${avg.toFixed(1)} · aprovado` : `${avg.toFixed(1)} · atenção`}</Badge> : <span className="text-muted-foreground">—</span>}</td></tr>})}</tbody></table></div><div className="hidden border-t border-border p-5 text-[10px] text-muted-foreground sm:flex sm:justify-between"><span>Documento gerado pelo nôskola · Secretaria pedagógica</span><span>Assinatura da Direcção: ____________________</span></div></section>}</div>;
}

const gradeFields = [
  { key: 'period1', label: 'P1' },
  { key: 'period2', label: 'P2' },
  { key: 'period3', label: 'P3' },
  { key: 'coordination', label: 'Coord.' },
  { key: 'average', label: 'Média' },
  { key: 'extraordinary', label: 'Época' },
] as const;

function Grades() {
  const classes = useGetClasses();
  const [classId, setClassId] = useState('');
  const [trimester, setTrimester] = useState('1');
  const id = Number(classId) || 0;
  const sheet = useGetGradeSheet(id, { query: { enabled: !!id, queryKey: getGetGradeSheetQueryKey(id) } });
  const trim = useGetGradeSheetForTrimester(id, Number(trimester), { query: { enabled: !!id, queryKey: getGetGradeSheetForTrimesterQueryKey(id, Number(trimester)) } });
  const update = useUpdateGradeSheet();
  const qc = useQueryClient();
  const data = trim.data ?? sheet.data;
  const [scores, setScores] = useState<Record<string, string>>({});

  useEffect(() => setScores({}), [id, trimester, data?.classGroupId]);

  const scoreKey = (studentId: number, subject: string, key: string) => `${studentId}-${subject}-${key}`;
  const setScore = (studentId: number, subject: string, key: string, value: string) => {
    setScores((current) => ({ ...current, [scoreKey(studentId, subject, key)]: value }));
  };
  const valueFor = (studentId: number, subject: string, key: typeof gradeFields[number]['key'], fallback: number | null | undefined) => {
    return scores[scoreKey(studentId, subject, key)] ?? (fallback === null || fallback === undefined ? '' : String(fallback));
  };
  const save = () => {
    if (!data) return;
    const students = data.students.map((student) => ({
      ...student,
      scores: student.scores.map((score) => {
        const next = { ...score };
        gradeFields.filter((field) => field.key !== 'average').forEach((field) => {
          const edited = scores[scoreKey(student.studentId, score.subject, field.key)];
          if (edited !== undefined) next[field.key] = edited === '' ? null : Number(edited);
        });
        const periods = [next.period1, next.period2, next.period3].filter((value): value is number => value !== null && value !== undefined);
        next.average = periods.length ? Math.round((periods.reduce((sum, value) => sum + value, 0) / periods.length) * 10) / 10 : null;
        return next;
      }),
    }));
    update.mutate({ classGroupId: id, data: { trimester: Number(trimester), subjects: data.subjects, students } }, {
      onSuccess: () => {
        setScores({});
        qc.invalidateQueries({ queryKey: getGetGradeSheetForTrimesterQueryKey(id, Number(trimester)) });
        qc.invalidateQueries({ queryKey: getGetGradeSheetQueryKey(id) });
      },
    });
  };
  const studentAverage = (student: NonNullable<typeof data>['students'][number]) => {
    const averages = student.scores.map((score) => {
      const periods = [score.period1, score.period2, score.period3].map((value, index) => {
        const field = gradeFields[index];
        const current = scores[scoreKey(student.studentId, score.subject, field.key)];
        return current === undefined ? value : current === '' ? null : Number(current);
      }).filter((value): value is number => value !== null && value !== undefined && !Number.isNaN(value));
      return periods.length ? periods.reduce((sum, value) => sum + value, 0) / periods.length : null;
    }).filter((value): value is number => value !== null);
    return averages.length ? averages.reduce((sum, value) => sum + value, 0) / averages.length : null;
  };

  return <div className="animate-in">
    <PageIntro eyebrow="avaliação oficial" title="Pautas e notas" copy="Registe as notas dos três períodos, provas de coordenação, médias e época." action={data ? <div className="flex gap-2"><Button variant="ghost" onClick={() => window.print()} data-testid="button-print-grades"><Printer size={16} /> Imprimir A4 horizontal</Button><Button onClick={save} disabled={update.isPending} data-testid="button-save-grades">{update.isPending ? 'A guardar…' : 'Guardar alterações'}</Button></div> : undefined} />
    <div className="mb-5 flex flex-col gap-3 rounded-2xl border border-border bg-card p-4 sm:flex-row sm:items-end">
      <Select label="Classe" value={classId} onChange={(event) => setClassId(event.target.value)} data-testid="select-grade-class"><option value="">Escolher classe…</option>{classes.data?.map((group) => <option key={group.id} value={group.id}>{group.name} · {group.academicYear}</option>)}</Select>
      <Select label="Trimestre" value={trimester} onChange={(event) => setTrimester(event.target.value)} data-testid="select-grade-trimester"><option value="1">1.º trimestre</option><option value="2">2.º trimestre</option><option value="3">3.º trimestre</option></Select>
      <div className="hidden text-xs text-muted-foreground sm:block sm:pb-3"><CalendarDays size={15} className="mr-1 inline" /> P1, P2 e P3 correspondem aos períodos lectivos</div>
    </div>
    {!classId ? <div className="rounded-2xl border border-border bg-card"><Empty icon={ClipboardList} title="Escolha uma classe para começar" copy="Seleccione a turma e o trimestre para abrir a pauta oficial." /></div> : sheet.isLoading || trim.isLoading ? <Skeleton className="h-72" /> : sheet.isError || trim.isError ? <ErrorState retry={() => { sheet.refetch(); trim.refetch(); }} /> : !data ? <div className="rounded-2xl border border-border bg-card"><Empty icon={ClipboardList} title="Pauta vazia" copy="Esta classe ainda não tem alunos ou disciplinas configuradas." /></div> : <section className="print-sheet overflow-hidden rounded-2xl border border-border bg-card">
      <div className="border-b border-border bg-primary p-5 text-primary-foreground md:p-6"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-widest text-accent">Documento oficial · classificação</p><h2 className="mt-2 font-display text-2xl font-bold">{data.className}</h2><p className="mt-1 text-xs text-primary-foreground/60">Ano lectivo {data.academicYear} · {data.trimester}.º trimestre</p></div><div className="hidden h-12 w-12 items-center justify-center rounded-xl bg-accent text-primary sm:flex"><GraduationCap size={25} /></div></div></div>
       <div className="overflow-x-auto"><table className="w-full min-w-[1800px] text-left text-[11px]"><thead className="bg-muted/50 text-[10px] uppercase tracking-wider text-muted-foreground"><tr><th className="sticky left-0 z-10 bg-muted/50 px-3 py-3" rowSpan={2}>Aluno</th>{data.subjects.map((subject) => <th key={subject} className="border-l border-border px-2 py-3 text-center" colSpan={6}>{subject}</th>)}<th className="border-l border-border px-3 py-3 text-center" rowSpan={2}>Média das médias</th></tr><tr>{data.subjects.flatMap((subject) => gradeFields.map((field) => <th key={`${subject}-${field.key}`} className="border-l border-border/60 px-1.5 py-2 text-center font-normal">{field.label}</th>))}</tr></thead><tbody className="divide-y divide-border">{data.students.map((student) => { const finalAverage = studentAverage(student); return <tr key={student.studentId} className="hover:bg-muted/20" data-testid={`row-grade-${student.studentId}`}><td className="sticky left-0 z-10 bg-card px-3 py-3"><p className="max-w-40 truncate font-bold">{student.studentName}</p><p className="font-mono text-[10px] text-muted-foreground">{student.studentCode}</p></td>{data.subjects.flatMap((subject) => { const score = student.scores.find((item) => item.subject === subject); return gradeFields.map((field) => <td key={`${student.studentId}-${subject}-${field.key}`} className="border-l border-border/50 px-1 py-2 text-center">{field.key === 'average' ? <span className="font-mono font-bold">{score?.average?.toFixed(1) ?? '—'}</span> : <input type="number" min="0" max="20" step=".1" value={valueFor(student.studentId, subject, field.key, score?.[field.key])} onChange={(event) => setScore(student.studentId, subject, field.key, event.target.value)} className="h-8 w-12 rounded-md border border-input bg-background px-1 text-center font-mono text-[11px] outline-none focus:border-accent" aria-label={`${student.studentName} ${subject} ${field.label}`} data-testid={`input-grade-${student.studentId}-${subject}-${field.key}`} />}</td>)})}<td className="border-l border-border px-2 py-2 text-center">{finalAverage !== null ? <Badge tone={finalAverage >= 10 ? 'good' : 'bad'}>{finalAverage.toFixed(1)}</Badge> : <span className="text-muted-foreground">—</span>}</td></tr>; })}</tbody></table></div>
      <div className="hidden border-t border-border p-5 text-[10px] text-muted-foreground sm:flex sm:justify-between"><span>Documento gerado pelo nôskola · Secretaria pedagógica</span><span>Assinatura da Direcção: ____________________</span></div>
    </section>}
  </div>;
}

function DocumentsPage() {
  const students = useGetStudents();
  const classes = useGetClasses();
  const [studentId, setStudentId] = useState('');
  const [kind, setKind] = useState<'declaration' | 'certificate'>('declaration');
  const student = students.data?.find((item) => item.id === Number(studentId));
  const group = classes.data?.find((item) => item.id === student?.classGroupId);
  const title = kind === 'declaration' ? 'Declaração de matrícula' : 'Certificado de aproveitamento';

  return <div className="animate-in">
    <div className="no-print"><PageIntro eyebrow="secretaria pedagógica" title="Documentos oficiais" copy="Emita declarações e certificados prontos para imprimir e assinar." /></div>
    <div className="no-print mb-5 grid gap-3 rounded-2xl border border-border bg-card p-4 sm:grid-cols-[1fr_240px_auto] sm:items-end">
      <Select label="Aluno" value={studentId} onChange={(event) => setStudentId(event.target.value)} data-testid="select-document-student"><option value="">Escolher aluno…</option>{students.data?.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.studentCode}</option>)}</Select>
      <Select label="Tipo de documento" value={kind} onChange={(event) => setKind(event.target.value as 'declaration' | 'certificate')} data-testid="select-document-kind"><option value="declaration">Declaração de matrícula</option><option value="certificate">Certificado de aproveitamento</option></Select>
      <Button variant="soft" disabled={!student} onClick={() => window.print()} data-testid="button-print-document"><Printer size={16} /> Imprimir documento</Button>
    </div>
    {!student ? <div className="no-print rounded-2xl border border-border bg-card"><Empty icon={FileText} title="Escolha um aluno" copy="Seleccione um aluno para preparar o documento oficial." /></div> : <section className="print-sheet mx-auto max-w-4xl rounded-2xl border border-border bg-card p-8 text-center md:p-14">
      <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-2xl bg-accent text-primary"><GraduationCap size={31} /></div>
      <p className="mt-7 font-mono text-[10px] uppercase tracking-[.22em] text-muted-foreground">República da Guiné-Bissau · Ministério da Educação</p>
      <h2 className="mt-5 font-display text-3xl font-bold text-primary">Escola Comunitária de Bissau</h2>
      <div className="mx-auto mt-4 h-px max-w-xs bg-accent" />
      <h1 className="mt-10 font-display text-2xl font-bold">{title}</h1>
      <p className="mx-auto mt-8 max-w-2xl text-left text-base leading-8 text-foreground">Certifica-se, para os devidos efeitos, que <strong>{student.name}</strong>, portador(a) do código de aluno <strong>{student.studentCode}</strong>, se encontra registado(a) nesta instituição no ano lectivo <strong>{group?.academicYear ?? '2025/2026'}</strong>, frequentando a classe <strong>{student.className}</strong>.</p>
      {kind === 'certificate' && <div className="mx-auto mt-7 max-w-md rounded-xl border border-border bg-muted/30 p-4 text-left text-sm"><p className="font-bold">Resultado académico</p><p className="mt-2 text-muted-foreground">Documento emitido pela secretaria pedagógica, sujeito à validação e assinatura da Direcção.</p></div>}
      <p className="mt-14 text-right text-sm text-muted-foreground">Bissau, ____ de __________________ de 2025</p>
      <div className="mt-14 grid grid-cols-2 gap-12 text-xs text-muted-foreground"><span className="border-t border-foreground/30 pt-2">A Secretaria</span><span className="border-t border-foreground/30 pt-2">A Direcção</span></div>
      <p className="mt-12 font-mono text-[9px] uppercase tracking-widest text-muted-foreground">nôskola · gestão escolar</p>
    </section>}
  </div>;
}

function SettingsPage() { const [saved, setSaved] = useState(false); const [v, setV] = useState({ name: 'Escola Comunitária de Bissau', city: 'Bissau', contact: 'Dulce Gomes', email: 'direcao@ecb.gw', phone: '+245 955 21 40', year: '2025/2026' }); return <div className="animate-in"><PageIntro eyebrow="configuração" title="Definições" copy="A identidade da escola e o ciclo lectivo actual." /><div className="grid gap-5 lg:grid-cols-[240px_1fr]"><nav className="flex gap-2 overflow-x-auto lg:block lg:space-y-1">{['Perfil da escola', 'Ano lectivo', 'Preferências'].map((x, i) => <button key={x} className={`whitespace-nowrap rounded-lg px-3 py-2 text-left text-sm font-bold ${i === 0 ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted'}`} data-testid={`button-settings-${i}`}>{x}</button>)}</nav><section className="rounded-2xl border border-border bg-card p-5 md:p-7"><div className="mb-7 flex items-start gap-4 border-b border-border pb-6"><div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-accent text-primary"><GraduationCap size={27} /></div><div><h2 className="font-display text-xl font-bold">Perfil da escola</h2><p className="mt-1 text-sm text-muted-foreground">Estes dados aparecem nos documentos oficiais.</p></div></div><div className="grid gap-5 sm:grid-cols-2"><Input label="Nome da escola" value={v.name} onChange={e => setV({ ...v, name: e.target.value })} data-testid="input-settings-name" /><Input label="Cidade" value={v.city} onChange={e => setV({ ...v, city: e.target.value })} data-testid="input-settings-city" /><Input label="Direcção / contacto" value={v.contact} onChange={e => setV({ ...v, contact: e.target.value })} data-testid="input-settings-contact" /><Input label="Email institucional" type="email" value={v.email} onChange={e => setV({ ...v, email: e.target.value })} data-testid="input-settings-email" /><Input label="Telefone" value={v.phone} onChange={e => setV({ ...v, phone: e.target.value })} data-testid="input-settings-phone" /><Select label="Ano lectivo em curso" value={v.year} onChange={e => setV({ ...v, year: e.target.value })} data-testid="select-settings-year"><option>2025/2026</option><option>2024/2025</option><option>2023/2024</option></Select></div><div className="mt-7 flex items-center justify-end gap-3 border-t border-border pt-5"><span className={`text-xs text-secondary-foreground ${saved ? 'opacity-100' : 'opacity-0'}`}>Alterações guardadas</span><Button onClick={() => { setSaved(true); setTimeout(() => setSaved(false), 2500); }} data-testid="button-save-settings"><Check size={16} /> Guardar definições</Button></div></section></div></div>; }

type InformaticsStudent = { id: number; name: string; code: string; level: string; p1: string; p2: string; p3: string };
const informaticsKey = 'noskola-informatics-students';
const defaultInformaticsStudents: InformaticsStudent[] = [
  { id: 1, name: 'Malam Sané', code: 'INF-0001', level: 'Informática - Nível I', p1: '15', p2: '16', p3: '' },
  { id: 2, name: 'Aissatu Baldé', code: 'INF-0002', level: 'Informática - Nível I', p1: '17', p2: '', p3: '' },
];
function Informatics() {
  const [students, setStudents] = useState<InformaticsStudent[]>(() => { try { return JSON.parse(localStorage.getItem(informaticsKey) ?? 'null') ?? defaultInformaticsStudents; } catch { return defaultInformaticsStudents; } });
  const [form, setForm] = useState({ name: '', level: 'Informática - Nível I' });
  const [showForm, setShowForm] = useState(false);
  const persist = (next: InformaticsStudent[]) => { setStudents(next); localStorage.setItem(informaticsKey, JSON.stringify(next)); };
  const add = (event: FormEvent) => { event.preventDefault(); if (!form.name.trim()) return; persist([...students, { id: Date.now(), name: form.name.trim(), code: `INF-${String(students.length + 1).padStart(4, '0')}`, level: form.level, p1: '', p2: '', p3: '' }]); setForm({ name: '', level: 'Informática - Nível I' }); setShowForm(false); };
  const score = (id: number, field: 'p1' | 'p2' | 'p3', value: string) => persist(students.map((student) => student.id === id ? { ...student, [field]: value } : student));
  return <div className="animate-in"><PageIntro eyebrow="curso técnico" title="Informática" copy="Matricule alunos e lance as notas do curso de Informática." action={<div className="flex gap-2"><Button variant="ghost" onClick={() => window.print()}><Printer size={16} /> Imprimir pauta</Button><Button onClick={() => setShowForm(!showForm)}><Plus size={17} /> Matricular aluno</Button></div>} />
    <div className="mb-5 grid gap-3 sm:grid-cols-3"><Stat icon={Users} label="Alunos matriculados" value={String(students.length)} tone="green" /><Stat icon={Laptop} label="Curso" value="Informática" tone="dark" /><Stat icon={ClipboardList} label="Níveis activos" value="2" tone="yellow" /></div>
    {showForm && <form onSubmit={add} className="mb-5 grid gap-3 rounded-2xl border border-accent/60 bg-accent/10 p-5 sm:grid-cols-[1fr_280px_auto] sm:items-end"><Input label="Nome completo" required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /><Select label="Nível do curso" value={form.level} onChange={(event) => setForm({ ...form, level: event.target.value })}><option>Informática - Nível I</option><option>Informática - Nível II</option><option>Programação e Redes</option></Select><Button type="submit"><Check size={16} /> Confirmar matrícula</Button></form>}
    <section className="overflow-hidden rounded-2xl border border-border bg-card"><div className="border-b border-border p-5"><h2 className="font-display text-lg font-bold">Pauta de Informática</h2><p className="mt-1 text-xs text-muted-foreground">Notas de P1, P2 e P3 guardadas neste dispositivo.</p></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-muted/40 text-[10px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3">Aluno</th><th className="px-5 py-3">Nível</th><th className="px-3 py-3 text-center">P1</th><th className="px-3 py-3 text-center">P2</th><th className="px-3 py-3 text-center">P3</th><th className="px-5 py-3 text-center">Média</th></tr></thead><tbody className="divide-y divide-border">{students.map((student) => { const grades = [student.p1, student.p2, student.p3].map(Number).filter((value) => !Number.isNaN(value)); const average = grades.length ? (grades.reduce((sum, value) => sum + value, 0) / grades.length).toFixed(1) : '—'; return <tr key={student.id}><td className="px-5 py-4"><p className="font-bold">{student.name}</p><p className="font-mono text-[10px] text-muted-foreground">{student.code}</p></td><td className="px-5 py-4 text-xs text-muted-foreground">{student.level}</td>{(['p1', 'p2', 'p3'] as const).map((field) => <td key={field} className="px-3 py-4 text-center"><input type="number" min="0" max="20" step="0.1" value={student[field]} onChange={(event) => score(student.id, field, event.target.value)} className="h-9 w-16 rounded-md border border-input bg-background px-1 text-center font-mono text-xs" /></td>)}<td className="px-5 py-4 text-center font-mono font-bold">{average}</td></tr>; })}</tbody></table></div></section>
  </div>;
}
function NotFound() { return <div className="flex min-h-[70vh] flex-col items-center justify-center text-center"><div className="font-mono text-6xl font-bold text-accent">404</div><h1 className="mt-4 font-display text-2xl font-bold">Página não encontrada</h1><Link href="/" className="mt-5 text-sm font-bold text-secondary-foreground hover:underline" data-testid="link-back-home">Voltar à visão geral</Link></div>; }
function Router() { return <Shell><Switch><Route path="/" component={Dashboard} /><Route path="/schools" component={Schools} /><Route path="/classes" component={Classes} /><Route path="/students" component={Students} /><Route path="/finance" component={Finance} /><Route path="/grades" component={Grades} /><Route path="/informatics" component={Informatics} /><Route path="/documents" component={DocumentsPage} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></Shell>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><ErrorBoundary><Router /></ErrorBoundary><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;